    public Set<Map.Entry<String, String>> getAllAttributes() {
        return attributes.entrySet();
    }

    public static void main(String[] args) {
        CustomAttributes customAttributes1 = new CustomAttributes();
        customAttributes1.addAttribute("key1", "value1");
        customAttributes1.addAttribute("key2", "value2");

        CustomAttributes customAttributes2 = new CustomAttributes();
        customAttributes2.addAttribute("key3", "value3");
        customAttributes2.addAttribute("key4", "value4");

        System.out.println("Attributes before merging:");
        customAttributes1.getAllAttributes().forEach(entry -> System.out.println(entry.getKey() + ": " + entry.getValue()));

        customAttributes1.mergeAttributes(customAttributes2);

        System.out.println("\nAttributes after merging:");
        customAttributes1.getAllAttributes().forEach(entry -> System.out.println(entry.getKey() + ": " + entry.getValue()));

        customAttributes1.removeAttribute("key2");

        System.out.println("\nAttributes after removing 'key2':");
