```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class DedupFunctionInfo {
    private String field;
    private Function function;

    public DedupFunctionInfo(String field, Function function) {
        this.field = field;
        this.function = function;
    }

    public String getField() {
        return field;
    }

    public Function getFunction() {
        return function;
    }

    public static List<DedupFunctionInfo> deduplicate(List<DedupFunctionInfo> functionInfos) {
        Map<String, DedupFunctionInfo> uniqueFields = new HashMap<>();
        List<DedupFunctionInfo> result = new ArrayList<>();

        for (DedupFunctionInfo info : functionInfos) {
            String field = info.getField();
            if (!uniqueFields.containsKey(field)) {
                uniqueFields.put(field, info);
                result.add(info);
            }
        }

        return result;
    }
