import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;

import java.lang.reflect.Method;
import java.util.Objects;
import java.util.Optional;

public class SpELExpressionEvaluator {
    public <T> Optional<T> evaluateMethodExpression(Method method, Object[] arguments, String expression) {
        try {
            ExpressionParser parser = new SpelExpressionParser();
            StandardEvaluationContext context = new StandardEvaluationContext();

            // Add method arguments as variables to the evaluation context
            String[] parameterNames = new LocalVariableTableParameterNameDiscoverer().getParameterNames(method);
            if (parameterNames != null) {
                for (int i = 0; i < parameterNames.length; i++) {
                    context.setVariable(parameterNames[i], arguments[i]);
                }
            }

            // Create and evaluate the expression within the context
            Expression exp = parser.parseExpression(expression);
            T result = exp.getValue(context, method.getReturnType());

            return Optional.ofNullable(result);
        } catch (Exception e) {
            return Optional.empty();
        }
    }
}
