import org.apache.axis2.handlers.AbstractHandler;

public class CustomMessageHandler extends AbstractHandler {

    @Override
    public InvocationResponse invoke(MessageContext messageContext) throws AxisFault {
        // Extract the endpoint reference (EPR) from the message context
        EndpointReference epr = messageContext.getTo();
        String endpointReference = epr.getAddress();

        // Retrieve the operation name associated with the incoming message
        AxisOperation axisOperation = messageContext.getAxisOperation();
        String operationName = axisOperation.getName().getLocalPart();

        // Print the extracted EPR and operation name to the console
        System.out.println("Endpoint Reference: " + endpointReference);
        System.out.println("Operation Name: " + operationName);

        return InvocationResponse.CONTINUE;
    }
}
