import java.util.ArrayList;
import java.util.List;

public class MetricsSystem implements HasMetrics {
    private List<Metric> metricList;

    public MetricsSystem() {
        this.metricList = new ArrayList<>();
    }

    public void addMetric(String name, double value) {
        Metric newMetric = new Metric(name, value);
        metricList.add(newMetric);
    }

    @Override
    public List<Metric> metrics() {
        return new ArrayList<>(metricList);
    }

    public double calculateAverage() {
        if (metricList.isEmpty()) {
            return 0.0;
        }
        double sum = 0;
        for (Metric metric : metricList) {
            sum += metric.getValue();
        }
        return sum / metricList.size();
