Assume the following:
- The `Vector2` class represents a 2D vector with `x` and `y` coordinates.
- The distance between two points (x1, y1) and (x2, y2) in a 2D plane is given by the formula: `distance = sqrt((x2 - x1)^2 + (y2 - y1)^2)`, where `sqrt` denotes the square root.

```java
import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.utils.Array;

public class IslandDistanceCalculator {
    public Array<Vector2> otherIslandPos;

    // Method to calculate distances between the current island and other islands
    public Array<Float> calculateDistances(Vector2 currentIslandPos) {
        Array<Float> distances = new Array<>();

        for (Vector2 islandPos : otherIslandPos) {
            float distance = calculateDistance(currentIslandPos, islandPos);
            distances.add(distance);
        }

        return distances;
    }

    // Helper method to calculate distance between two 2D points
    private float calculateDistance(Vector2 pos1, Vector2 pos2) {
        float dx = pos2.x - pos1.x;
        float dy = pos2.y - pos1.y;
        return (float) Math.sqrt(dx * dx + dy * dy);
    }
}
