// Define the custom annotation @FormatValidation
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Retention(RetentionPolicy.SOURCE)
@Target(ElementType.FIELD)
public @interface FormatValidation {
    String regex();
}

// Implement the custom annotation processor
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import java.io.IOException;
import java.io.Writer;
import java.util.Set;

@SupportedAnnotationTypes("com.example.FormatValidation")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class FormatValidationProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(FormatValidation.class)) {
            if (element.getKind().isField()) {
                String fieldName = element.getSimpleName().toString();
                String regex = element.getAnnotation(FormatValidation.class).regex();
                String className = ((TypeElement) element.getEnclosingElement()).getQualifiedName().toString();
                generateValidationMethod(className, fieldName, regex);
            }
        }
        return true;
    }

    private void generateValidationMethod(String className, String fieldName, String regex) {
        String validationClassName = className + "Validator";
        String validationMethodName = "validate" + fieldName.substring(0, 1).toUpperCase() + fieldName.substring(1);

        try (Writer writer = processingEnv.getFiler().createSourceFile(validationClassName).openWriter()) {
            writer.write("public class " + validationClassName + " {\n");
            writer.write("    public static void " + validationMethodName + "(String " + fieldName + ") {\n");
            writer.write("        if (!" + fieldName + ".matches(\"" + regex + "\")) {\n");
            writer.write("            throw new IllegalArgumentException(\"Invalid " + fieldName + " format\");\n");
            writer.write("        }\n");
            writer.write("    }\n");
            writer.write("}\n");
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error generating validation method: " + e.getMessage());
        }
    }
}
```

This solution demonstrates the creation of a custom annotation `@FormatValidation` and an annotation processor `FormatValidationProcessor` to generate validation methods based on the annotated fields. The processor identifies the annotated fields, extracts the necessary information, and generates a validation method in a separate validation class. The generated validation method checks if the field value matches the specified regular expression and throws an exception if the validation fails.

