public SPExpression analyze(Context context) {
    // Perform semantic analysis and type checking for the left-hand side and right-hand side expressions
    lhs = lhs.analyze(context);
    rhs = rhs.analyze(context);

    // Ensure that the division operation is valid and handle division by zero
    if (lhs.getType() != Type.INT || rhs.getType() != Type.INT) {
        // Handle error: Division operands must be of type INT
        throw new SemanticException("Division operands must be of type INT", line);
    } else if (rhs instanceof SPIntLiteral && ((SPIntLiteral) rhs).getValue() == 0) {
        // Handle error: Division by zero
        throw new SemanticException("Division by zero is not allowed", line);
    }

    // Return the result of the division operation if it is valid
    return new SPDivisionOp(line, lhs, rhs);
}
```

