public class RetryTest {
    private final RetryConfig retryConfig;

    public RetryTest(RetryConfig retryConfig) {
        this.retryConfig = retryConfig;
    }

    public void retryTest(Runnable testMethod) {
        int retries = 0;
        while (retries < retryConfig.getMaxRetries()) {
            try {
                testMethod.run();
                return; // Test passed, no need to retry
            } catch (Exception e) {
                retries++;
                if (retries < retryConfig.getMaxRetries()) {
                    try {
