        if (facilityStartTime == 0) {
            facilityStartTime = timestamp;
        }
    }

    public void leave(int resourceId, int timestamp) {
        totalUtilizationTime += timestamp - entryTimes.get(resourceId);
        entryTimes.remove(resourceId);
    }

    public double utilization(int timestamp) {
        if (entryTimes.isEmpty()) {
            return 0;
        }
        int operationalTime = timestamp - facilityStartTime;
        return (double) totalUtilizationTime / operationalTime;
    }
}
