import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.github.fge.jsonpatch.JsonPatch;
import com.github.fge.jsonpatch.JsonPatchException;
import com.github.fge.jsonpatch.JsonPatchOperation;

import java.util.List;
import java.util.Map;

public class JsonPatchApplier {

    public static Map<String, Object> applyPatch(Map<String, Object> jsonObject, List<PatchOperation> operations) {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode jsonNode = mapper.valueToTree(jsonObject);

        for (PatchOperation operation : operations) {
            if (operation.getType().equals("remove")) {
                String path = operation.getPath();
                JsonPatchOperation removeOperation = new JsonPatchOperation("remove", path);
                JsonPatch patch = JsonPatch.fromJson(mapper.createArrayNode().add(removeOperation));
                try {
                    jsonNode = patch.apply(jsonNode);
                } catch (JsonPatchException e) {
                    e.printStackTrace();
                }
            }
        }

        return mapper.convertValue(jsonNode, Map.class);
    }

    public static void main(String[] args) {
        Map<String, Object> jsonObject = Map.of("description", "description1");
        List<PatchOperation> operations = List.of(new PatchOperation("remove", "/description"));

        Map<String, Object> modifiedObject = applyPatch(jsonObject, operations);
        System.out.println(modifiedObject); // Output: {}
    }
}
```

