        // Criteria 1: Accept all files with a .java extension
        if (file.getName().toLowerCase().endsWith(".java")) {
            return true;
        }

        // Criteria 2: Reject all files with a name starting with "test" (case insensitive)
        if (file.getName().toLowerCase().startsWith("test")) {
            return false;
        }

        // Criteria 3: Accept all files located in a directory named "src"
        VirtualFile srcDirectory = project.getBaseDir().findChild("src");
        if (srcDirectory != null && file.getPath().startsWith(srcDirectory.getPath())) {
            return true;
        }

        // Default: Reject all other files
        return false;
    }
}
