                }
            };

            // Install the all-trusting trust manager
            SSLContext sslContext = SSLContext.getInstance("SSL");
            sslContext.init(null, trustAllCerts, new SecureRandom());

            // Set up the connection
            URL url = new URL(APNS_FEEDBACK_URL);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setSSLSocketFactory(sslContext.getSocketFactory());
            conn.setRequestMethod("GET");

            // Retrieve the feedback data
            InputStream input = conn.getInputStream();
            DataInputStream dis = new DataInputStream(input);
            while (dis.available() > 0) {
                // Process the feedback data to obtain inactive device tokens
                byte[] tokenBytes = new byte[32];
                dis.readFully(tokenBytes);
                String deviceToken = bytesToHex(tokenBytes);
                inactiveDeviceTokens.add(deviceToken);
            }

            // Close the connections
            dis.close();
            conn.disconnect();
        } catch (Exception e) {
