import java.io.*;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

class Pipe {
    private BlockingQueue<String> queue = new LinkedBlockingQueue<>();

    public void write(String data) {
        try {
            queue.put(data);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public String read() {
        try {
            return queue.take();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }
}

class Inputer {
    private String inputFile;
    private Pipe outputPipe;

    public Inputer(String inputFile, Pipe outputPipe) {
        this.inputFile = inputFile;
        this.outputPipe = outputPipe;
        startReading();
    }

    private void startReading() {
        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new FileReader(inputFile))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputPipe.write(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }
}

class Processor {
    private Pipe inputPipe;
    private Pipe outputPipe;

    public Processor(Pipe inputPipe, Pipe outputPipe) {
        this.inputPipe = inputPipe;
        this.outputPipe = outputPipe;
        startProcessing();
    }

    private void startProcessing() {
        new Thread(() -> {
            String data;
            while ((data = inputPipe.read()) != null) {
                // Perform processing on data
                String processedData = data.toUpperCase(); // Example processing
                outputPipe.write(processedData);
            }
        }).start();
    }
}

class Outputer {
    private String outputFile;
    private Pipe inputPipe;

    public Outputer(String outputFile, Pipe inputPipe) {
        this.outputFile = outputFile;
        this.inputPipe = inputPipe;
        startWriting();
    }

    private void startWriting() {
        new Thread(() -> {
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {
                String data;
                while ((data = inputPipe.read()) != null) {
                    writer.write(data);
                    writer.newLine();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }
}

