        this.testResults = new ArrayList<>();
    }

    /**
     * Add a new test result to the list.
     * @param result the test result to add
     */
    public void addTestResult(int result) {
        testResults.add(result);
    }

    /**
     * Remove a test result from the list based on the given index.
     * @param index the index of the test result to remove
     */
    public void removeTestResult(int index) {
        if (index >= 0 && index < testResults.size()) {
            testResults.remove(index);
        } else {
            throw new IndexOutOfBoundsException("Index out of bounds");
        }
    }

    /**
     * Retrieve the average score of all test results in the list.
     * @return the average score of all test results
     */
    public double getAverageScore() {
        if (testResults.isEmpty()) {
            return 0.0;
        }
        int sum = 0;
        for (int result : testResults) {
            sum += result;
        }
        return (double) sum / testResults.size();
    }
}
