                switch (extension) {
                    case "java":
                        return new ImageIcon("java_icon.png");
                    case "xml":
                        return new ImageIcon("xml_icon.png");
                    case "html":
                        return new ImageIcon("html_icon.png");
                    default:
                        return new ImageIcon("generic_file_icon.png");
                }
            }
        }
        return null;
    }
}
