import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class FilePoolDataGenerator {
    private long fileSizeMin;
    private long fileSizeMax;
    private int poolSize;
    private List<Long> filePool;
    private Random random;

    public FilePoolDataGenerator(long fileSizeMin, long fileSizeMax, int poolSize) {
        this.fileSizeMin = fileSizeMin;
        this.fileSizeMax = fileSizeMax;
        this.poolSize = poolSize;
        this.filePool = new ArrayList<>();
        this.random = new Random();

        init();
    }

    private synchronized void init() {
        if (filePool.isEmpty()) {
            for (int i = 0; i < poolSize; i++) {
                filePool.add(generateRandomFileSize());
            }
        }
    }

    public synchronized void addFileToPool() {
        if (filePool.size() < poolSize) {
            filePool.add(generateRandomFileSize());
        }
    }

    public synchronized void removeFileFromPool() {
        if (!filePool.isEmpty()) {
            filePool.remove(filePool.size() - 1);
        }
    }

    public synchronized long getTotalSizeOfPool() {
        long totalSize = 0;
        for (Long fileSize : filePool) {
            totalSize += fileSize;
        }
        return totalSize;
    }

    private long generateRandomFileSize() {
        return fileSizeMin + random.nextLong() % (fileSizeMax - fileSizeMin + 1);
    }
}
```

In the solution, the `FilePoolDataGenerator` class is completed with methods to add files to the pool, remove files from the pool, and get the total size of the pool. The class uses synchronization to ensure thread safety for concurrent access to the file pool. The `init` method initializes the file pool with random file sizes within the specified range. The `generateRandomFileSize` method generates a random file size within the specified range.

