import java.util.HashMap;
import java.util.Map;

public class ParseURL {
    public static Map<String, String> parseURL(String url) {
        Map<String, String> parsedComponents = new HashMap<>();

        String[] parts = url.split("://|/|\\?|:");

        parsedComponents.put("protocol", parts[0]);
        parsedComponents.put("domain", parts[1]);

        if (parts.length > 2) {
            if (parts[2].matches("\\d+")) {
                parsedComponents.put("port", parts[2]);
                if (parts.length > 3) {
                    parsedComponents.put("path", "/" + parts[3]);
                    if (parts.length > 4) {
                        parsedComponents.put("query", parts[4]);
                    } else {
                        parsedComponents.put("query", "");
                    }
                } else {
                    parsedComponents.put("path", "");
                    parsedComponents.put("query", "");
                }
            } else {
                parsedComponents.put("port", "");
                parsedComponents.put("path", "/" + parts[2]);
                if (parts.length > 3) {
                    parsedComponents.put("query", parts[3]);
                } else {
                    parsedComponents.put("query", "");
                }
            }
        } else {
            parsedComponents.put("port", "");
            parsedComponents.put("path", "");
            parsedComponents.put("query", "");
        }

        return parsedComponents;
    }
}
