import javax.servlet.*;
import java.io.IOException;

public class SystemFilter implements Filter {

    private RedisDao redisDao = new RedisDao(); // Assuming RedisDao class exists

    private static List<String> anonlist;
    private static List<String> access_token_list;
    private static PatternMatcher pathMatcher = new AntPathMatcher();
    static final Logger log = Logger.getLogger(SystemFilter.class);

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        // Load anonymous paths and access tokens from Redis or configuration
        anonlist = redisDao.getAnonymousPaths();
        access_token_list = redisDao.getAccessTokens();
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
        String requestPath = ((HttpServletRequest) request).getRequestURI();

        if (isAnonymousPath(requestPath) || isValidAccessToken(request)) {
            chain.doFilter(request, response); // Allow the request to proceed
        } else {
            // Deny the request
            HttpServletResponse httpResponse = (HttpServletResponse) response;
            httpResponse.setStatus(HttpServletResponse.SC_FORBIDDEN);
            log.warn("Access denied for request to: " + requestPath);
        }
    }

    private boolean isAnonymousPath(String requestPath) {
        for (String anonPath : anonlist) {
            if (pathMatcher.match(anonPath, requestPath)) {
                return true;
            }
        }
        return false;
    }

    private boolean isValidAccessToken(ServletRequest request) {
        String accessToken = ((HttpServletRequest) request).getHeader("Authorization");
        return access_token_list.contains(accessToken);
    }

    @Override
    public void destroy() {
        // Clean up any resources if needed
    }
}
```

