import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CustomGrammarLexer {
    public static List<String> tokenizeInput(String input, String grammarSpecification) {
        List<String> tokens = new ArrayList<>();
        String[] rules = grammarSpecification.split("\n");

        for (String rule : rules) {
            String[] parts = rule.split("\\|");
            String pattern = parts[0].trim();
            String token = parts[1].trim();

            Pattern p = Pattern.compile(pattern);
            Matcher m = p.matcher(input);

            while (m.find()) {
                tokens.add(token);
            }
        }
        return tokens;
    }

    public static void main(String[] args) {
        String grammarSpecification = "'N' 'O' | T:<Answer.NO>\n" +
                "'Y' 'ES' | T:<Answer.YES>\n" +
                "( 'Z' | B:<Letter.Z> ) B:<Letter.Z> 'ero' | T:<Bit.ZERO>";

        String input = "YES Zero";
        List<String> result = tokenizeInput(input, grammarSpecification);
        System.out.println(result);
    }
}
