import java.util.function.Function;
import java.util.function.Predicate;

public class ConditionalComputation {
    public static <T, R> R computeIfMatch(T target, Predicate<T> predicate, Function<T, R> mapping) {
        return predicate.test(target) ? mapping.apply(target) : null;
    }

    public static void main(String[] args) {
        // Example usage
        String input = "Hello";
        Predicate<String> isLongString = s -> s.length() > 5;
        Function<String, Integer> stringLength = String::length;

        // Compute the length of the input string if it's longer than 5 characters
        Integer result = computeIfMatch(input, isLongString, stringLength);
        System.out.println("Result: " + result);  // Output: Result: 5 (if input is "Hello")
    }
}
