import java.io.File;

public class FileCounter {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java FileCounter <directory_path> <file_extension>");
            return;
        }

        String directoryPath = args[0];
        String fileExtension = args[1];
        File directory = new File(directoryPath);

        if (!directory.exists() || !directory.isDirectory()) {
            System.out.println("Invalid directory path");
            return;
        }

        int fileCount = countFilesWithExtension(directory, fileExtension);
        System.out.println("Total files with extension ." + fileExtension + ": " + fileCount);
    }

    public static int countFilesWithExtension(File directory, String fileExtension) {
        int count = 0;
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    count += countFilesWithExtension(file, fileExtension); // Recursively count files in subdirectories
                } else if (file.getName().toLowerCase().endsWith("." + fileExtension.toLowerCase())) {
                    count++;
                }
            }
        }

        return count;
    }
}
