import java.lang.annotation.*;
import java.util.HashMap;
import java.util.Map;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Bean {
}

class DependencyInjector {
    private Map<Class<?>, Object> beans = new HashMap<>();

    public void registerBean(Class<?> beanClass) {
        try {
            Object beanInstance = beanClass.getDeclaredConstructor().newInstance();
            beans.put(beanClass, beanInstance);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public <T> T getBean(Class<T> beanClass) {
        try {
            T beanInstance = beanClass.cast(beans.get(beanClass));
            injectDependencies(beanInstance);
            return beanInstance;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private <T> void injectDependencies(T bean) {
        for (var field : bean.getClass().getDeclaredFields()) {
            if (field.isAnnotationPresent(Inject.class)) {
                try {
                    field.setAccessible(true);
                    Object dependency = beans.get(field.getType());
                    field.set(bean, dependency);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

class MQListener {
    public void listen() {
        System.out.println("Listening to MQ");
    }
}

class Service {
    @Inject
    private MQListener listener;

    public void performAction() {
        listener.listen();
    }
}

class Main {
    public static void main(String[] args) {
        DependencyInjector injector = new DependencyInjector();
        injector.registerBean(MQListener.class);
        injector.registerBean(Service.class);

        Service service = injector.getBean(Service.class);
        service.performAction();
    }
}
