        System.out.print("Enter the filename: ");
        String filename = inputScanner.nextLine();
        System.out.print("Enter the value of N: ");
        int N = inputScanner.nextInt();

        WordFrequencyCounter counter = new WordFrequencyCounter();
        Map<String, Integer> wordCount = counter.countWords(filename);

        List<Map.Entry<String, Integer>> sortedWordCount = new ArrayList<>(wordCount.entrySet());
        sortedWordCount.sort((entry1, entry2) -> entry2.getValue().compareTo(entry1.getValue()));

        System.out.println("Top " + N + " most frequently occurring words:");
        for (int i = 0; i < N && i < sortedWordCount.size(); i++) {
            Map.Entry<String, Integer> entry = sortedWordCount.get(i);
            System.out.println(entry.getKey() + " - " + entry.getValue());
        }
    }
}
