import org.assertj.core.api.SoftAssertions;

import java.util.Map;

public class DefinitionValidator {
    public void validateDefinitionProperties(String definitionName, Map<String, Property> expectedDefinitionProperties, Map<String, Property> actualDefinitionProperties) {
        SoftAssertions softAssertions = new SoftAssertions();

        if (actualDefinitionProperties != null && !actualDefinitionProperties.isEmpty()) {
            softAssertions.assertThat(actualDefinitionProperties.keySet())
                    .as("Checking properties of definition '%s'", definitionName)
                    .containsAll(expectedDefinitionProperties.keySet());

            for (Map.Entry<String, Property> expectedDefinitionPropertyEntry : expectedDefinitionProperties.entrySet()) {
                Property expectedDefinitionProperty = expectedDefinitionPropertyEntry.getValue();
                Property actualDefinitionProperty = actualDefinitionProperties.get(expectedDefinitionPropertyEntry.getKey());
                String propertyName = expectedDefinitionPropertyEntry.getKey();
                validateProperty(softAssertions, actualDefinitionProperty, expectedDefinitionProperty, propertyName, definitionName);
            }
        } else {
            softAssertions.assertThat(actualDefinitionProperties)
                    .as("Checking properties of definition '%s'", definitionName)
                    .isNullOrEmpty();
        }

        softAssertions.assertAll();
    }

    private void validateProperty(SoftAssertions softAssertions, Property actualProperty, Property expectedProperty, String propertyName, String definitionName) {
        softAssertions.assertThat(actualProperty)
                .as("Checking property '%s' of definition '%s'", propertyName, definitionName)
                .isNotNull();

        // Additional validation logic for property values can be added here
        // Example: softAssertions.assertThat(actualProperty.getValue()).isEqualTo(expectedProperty.getValue());
    }
}
```

