                                 @NotNull File repositoryDir,
                                 @NotNull RevisionCacheType type,
                                 int cacheSize) {
    myConfig = config;
    myRepositoryDir = repositoryDir;
    myType = type;
    this.cacheSize = cacheSize;
    cacheMap = new ConcurrentHashMap<>(cacheSize);
    myCache = new RecentEntriesCache<>(cacheSize);
  }

  public void addRevision(String revision, boolean exists) {
    cacheMap.put(revision, exists);
    myCache.put(revision, exists);
    if (cacheMap.size() > cacheSize) {
      evictOldestEntry();
    }
  }

  public boolean containsRevision(String revision) {
    return cacheMap.containsKey(revision);
  }

  private void evictOldestEntry() {
    String oldestRevision = myCache.getOldestKey();
    if (oldestRevision != null) {
      cacheMap.remove(oldestRevision);
      myCache.remove(oldestRevision);
    }
  }

  // Other methods and implementation details can be added as per the requirements
}
