        double[] vec = {1.0, 2.0, 3.0};
        double[] vecEntity = {2.0, 1.0, 3.0};
        double distOrg = 2.0;

        double[] vecMoved = calculateMovedVector(vec, vecEntity, distOrg);
        System.out.println("vecMoved = (" + vecMoved[0] + ", " + vecMoved[1] + ", " + vecMoved[2] + ")");
    }

    public static double[] calculateMovedVector(double[] vec, double[] vecEntity, double distOrg) {
        double[] vecMoved = new double[3];
        vecMoved[0] = vec[0] + vecEntity[0] * distOrg;
        vecMoved[1] = vec[1] + vecEntity[1] * distOrg;
        vecMoved[2] = vec[2] + vecEntity[2] * distOrg;
        return vecMoved;
    }
}
