import javax.websocket.Session;
import javax.websocket.RemoteEndpoint;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.IOException;

public class WebSocketClient {
    private Session session;
    private Logger logger = LoggerFactory.getLogger(WebSocketClient.class);

    public void setSession(Session session) {
        this.session = session;
    }

    public void sendMessage(String message) {
        if (this.session == null) {
            logger.error("WebSocket session is not established");
            return;
        }

        RemoteEndpoint.Basic remote = this.session.getBasicRemote();
        try {
            remote.sendText(message);
        } catch (IOException e) {
            logger.error("Error occurred while sending message over WebSocket: " + e.getMessage());
        }
    }
}
