        byte capabilities = (byte) (getPageSpecificBytes()[6] & 0x10);
        return ByteUtils.hasBitSet(capabilities, 2);
    }

    public boolean isVirtualSpeed() {
        byte capabilities = (byte) (getPageSpecificBytes()[6] & 0x0F);
        return ByteUtils.hasBitSet(capabilities, 3);
    }

    public Optional<FecState> getFecState() {
        byte capabilities = (byte) (getPageSpecificBytes()[6] & 0x30);
        byte fecBit = (byte) (capabilities >> 4);

        if (fecBit == 1) {
            return Optional.of(FecState.ENABLED);
        } else if (fecBit == 0) {
            return Optional.of(FecState.DISABLED);
        } else {
            return Optional.of(FecState.UNKNOWN);
        }
    }
}
