        // Your implementation here
    }
}
```

For example, given the input list [1, 2, 3] and a combination length of 2, the expected output would be [[1, 2], [1, 3], [2, 3]].

You should ensure that the generated combinations are lexicographically sorted and that the input list may contain duplicate elements. The output combinations should not contain duplicates, and the order of elements within each combination should also be lexicographically sorted.

```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class CombinationGenerator {
    public List<List<Integer>> generateCombinations(List<Integer> inputList, int combinationLength) {
        List<List<Integer>> result = new ArrayList<>();
        if (inputList == null || inputList.isEmpty() || combinationLength <= 0) {
            return result;
        }
        List<Integer> currentCombination = new ArrayList<>();
        inputList.sort(Integer::compareTo); // Sort the input list
        generateCombinationsHelper(inputList, combinationLength, 0, currentCombination, result);
        return result;
    }

    private void generateCombinationsHelper(List<Integer> inputList, int combinationLength, int start,
                                            List<Integer> currentCombination, List<List<Integer>> result) {
        if (combinationLength == 0) {
            result.add(new ArrayList<>(currentCombination)); // Add a copy of the current combination to the result
            return;
        }
        for (int i = start; i <= inputList.size() - combinationLength; i++) {
            currentCombination.add(inputList.get(i)); // Add current element to the combination
            generateCombinationsHelper(inputList, combinationLength - 1, i + 1, currentCombination, result);
            currentCombination.remove(currentCombination.size() - 1); // Backtrack by removing the last element
            while (i < inputList.size() - 1 && inputList.get(i).equals(inputList.get(i + 1))) {
                i++; // Skip duplicate elements to avoid duplicate combinations
            }
        }
    }

    public static void main(String[] args) {
        CombinationGenerator generator = new CombinationGenerator();
        List<Integer> inputList = Arrays.asList(1, 2, 3);
        int combinationLength = 2;
        List<List<Integer>> combinations = generator.generateCombinations(inputList, combinationLength);
        System.out.println(combinations); // Output: [[1, 2], [1, 3], [2, 3]]
    }
}
```

