        super(options);
        mInputStream = is;
    }

    @Override
    public Bitmap call() {
        try {
            // Read the input stream into a byte array
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int length;
            while ((length = mInputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, length);
            }
            byte[] data = outputStream.toByteArray();

            // Decode the byte array into a bitmap
            BitmapFactory.Options bitmapOptions = new BitmapFactory.Options();
            bitmapOptions.inPreferredConfig = Bitmap.Config.ARGB_8888; // Adjust based on requirements
            Bitmap bitmap = BitmapFactory.decodeByteArray(data, 0, data.length, bitmapOptions);

            // Apply compression options
            bitmap = compressBitmap(bitmap, getOptions());

