import java.lang.annotation.*;
import java.lang.reflect.Method;

@Retention(RetentionPolicy.RUNTIME)
@interface ValidationMethod {
    String value();
}

class ValidationProcessor {
    boolean validate(String input, String validationType, Object obj) {
        Method[] methods = obj.getClass().getDeclaredMethods();
        for (Method method : methods) {
            if (method.isAnnotationPresent(ValidationMethod.class)) {
                ValidationMethod annotation = method.getAnnotation(ValidationMethod.class);
                if (annotation.value().equals(validationType)) {
                    try {
                        return (boolean) method.invoke(obj, input);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }
        }
        return false;
    }
}

// Example usage
class Validator {
    @ValidationMethod("length")
    boolean validateLength(String input) {
        return input.length() > 5;
    }

    @ValidationMethod("numeric")
    boolean validateNumeric(String input) {
        return input.matches("\\d+");
    }
}

public class Main {
    public static void main(String[] args) {
        ValidationProcessor processor = new ValidationProcessor();
        Validator validator = new Validator();

        String input = "12345";
        System.out.println("Length validation result: " + processor.validate(input, "length", validator));
        System.out.println("Numeric validation result: " + processor.validate(input, "numeric", validator));
    }
}
```

