import java.nio.FloatBuffer;
import org.lwjgl.BufferUtils;

public class VectorBufferCreator {
    public FloatBuffer createFloatBuffer(Vector3f[] vectors) {
        FloatBuffer retVerts = BufferUtils.createFloatBuffer(vectors.length * 3);
        for (Vector3f vec : vectors) {
            retVerts.put(vec.getX());
            retVerts.put(vec.getY());
            retVerts.put(vec.getZ());
        }
        return (FloatBuffer) retVerts.flip();
    }
}
