private void evalUpdate(){
    UpdCont upd = (UpdCont) s.pop(); // Pop the update from the stack
    Expr x = upd.x; // Retrieve the expression to be updated from the update

    // Apply the update to the expression
    switch (upd.op) {
        case ADD:
            x.setValue(x.getValue() + upd.value);
            break;
        case SUBTRACT:
            x.setValue(x.getValue() - upd.value);
            break;
        case MULTIPLY:
            x.setValue(x.getValue() * upd.value);
            break;
        case DIVIDE:
            if (upd.value != 0) {
                x.setValue(x.getValue() / upd.value);
            } else {
                // Handle division by zero error
                System.out.println("Error: Division by zero");
            }
            break;
        default:
            // Handle unsupported operation error
            System.out.println("Error: Unsupported operation");
    }
}
```

