import java.util.regex.Pattern;

public class WebLinkValidator {
    public List<String> validateWebLinks(List<String> webLinks) {
        List<String> validLinks = new ArrayList<>();
        Pattern pattern = Pattern.compile("^(http|https)://[a-zA-Z0-9-]+\\.[a-zA-Z]{2,}(\\.[a-zA-Z]{2,})?$");

        for (String link : webLinks) {
            if (pattern.matcher(link).matches()) {
                validLinks.add(link);
            }
        }
        return validLinks;
    }

    public static void main(String[] args) {
        WebLinkValidator validator = new WebLinkValidator();
        List<String> inputLinks = new ArrayList<>();
        inputLinks.add("http://www.example.com");
        inputLinks.add("https://invalid-link");
        inputLinks.add("ftp://anotherexample.net");
        inputLinks.add("https://valid-link.org");

        List<String> validLinks = validator.validateWebLinks(inputLinks);
        System.out.println(validLinks); // Output: ["http://www.example.com", "https://valid-link.org"]
    }
}
