import com.google.protobuf.Descriptors.Descriptor;
import com.google.protobuf.Descriptors.FileDescriptor;
import com.google.protobuf.Descriptors.FieldDescriptor;

import java.util.ArrayList;
import java.util.List;

public class ProtocolBufferParser {
    public static List<String> extractSelectors(String protocolBufferFile) {
        List<String> selectors = new ArrayList<>();
        try {
            FileDescriptor fileDescriptor = FileDescriptor.buildFrom(protocolBufferFile.getBytes());
            Descriptor systemParameterRuleDescriptor = fileDescriptor.findMessageTypeByName("SystemParameterRule");
            FieldDescriptor selectorField = systemParameterRuleDescriptor.findFieldByName("selector");

            for (Object rule : fileDescriptor.getExtensions(systemParameterRuleDescriptor)) {
                String selector = (String) selectorField.get(rule);
                selectors.add(selector);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return selectors;
    }

    public static void main(String[] args) {
        String protocolBufferFile = "your_protocol_buffer_file_data_here";
        List<String> selectors = extractSelectors(protocolBufferFile);
        for (String selector : selectors) {
            System.out.println(selector);
        }
    }
}
