import org.apache.flink.streaming.api.windowing.triggers.Trigger;
import org.apache.flink.streaming.api.windowing.windows.Window;

public class CustomWindowTrigger<W extends Window> extends WindowTrigger<W> {

    private final long maxDelayMills;

    private CustomWindowTrigger(long maxDelayMills) {
        this.maxDelayMills = maxDelayMills;
    }

    public static <W extends Window> CustomWindowTrigger<W> of(long maxDelayMills) {
        return new CustomWindowTrigger<>(maxDelayMills);
    }

    @Override
    public TriggerResult onElement(Object element, long timestamp, W window, TriggerContext ctx) throws Exception {
        // Register event time timer for the end of the window
        long triggerTime = window.maxTimestamp() + maxDelayMills;
        ctx.registerEventTimeTimer(triggerTime);
        return TriggerResult.CONTINUE;
    }

    @Override
    public TriggerResult onEventTime(long time, W window, TriggerContext ctx) throws Exception {
        // Fire and clear the window when the event time timer fires
        if (time == window.maxTimestamp() + maxDelayMills) {
            return TriggerResult.FIRE_AND_PURGE;
        }
        return TriggerResult.CONTINUE;
    }

    @Override
    public TriggerResult onProcessingTime(long time, W window, TriggerContext ctx) throws Exception {
        // Continue processing time
        return TriggerResult.CONTINUE;
    }

    @Override
    public void clear(W window, TriggerContext ctx) throws Exception {
        // Clear any state when the window is purged
    }
}
```

In the provided solution, a custom window trigger `CustomWindowTrigger` is implemented by extending the `WindowTrigger` class. The trigger logic is based on event time and processing time. The `onElement` method registers an event time timer for the end of the window, and the `onEventTime` method fires and clears the window when the event time timer fires. The `onProcessingTime` method continues processing time, and the `clear` method is used to clear any state when the window is purged. This implementation allows for custom trigger behavior based on event time and processing time, with a specified maximum delay.

