import java.util.HashMap;
import java.util.Map;

public class TransactionData {
    @Id
    private Long timestamp;
    @Indexed
    private Long amount;
    private Long current;

    // Constructor
    public TransactionData(Long timestamp, Long amount) {
        this.timestamp = timestamp;
        this.amount = amount;
        this.current = 0L;
    }

    // Getters and Setters
    public Long getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(Long timestamp) {
        this.timestamp = timestamp;
    }

    public Long getAmount() {
        return amount;
    }

    public void setAmount(Long amount) {
        this.amount = amount;
    }

    public Long getCurrent() {
        return current;
    }

    public void setCurrent(Long current) {
        this.current = current;
    }

    // Method to update current total amount
    public void updateCurrentTotal(Map<Long, Long> transactionMap) {
        for (Map.Entry<Long, Long> entry : transactionMap.entrySet()) {
            if (entry.getKey() <= timestamp) {
                current += entry.getValue();
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        TransactionData transaction1 = new TransactionData(100L, 500L);
        TransactionData transaction2 = new TransactionData(150L, 300L);

        Map<Long, Long> transactionMap = new HashMap<>();
        transactionMap.put(transaction1.getTimestamp(), transaction1.getAmount());
        transactionMap.put(transaction2.getTimestamp(), transaction2.getAmount());

        transaction1.updateCurrentTotal(transactionMap);
        transaction2.updateCurrentTotal(transactionMap);

        System.out.println("Current total at timestamp " + transaction1.getTimestamp() + ": " + transaction1.getCurrent());
        System.out.println("Current total at timestamp " + transaction2.getTimestamp() + ": " + transaction2.getCurrent());
    }
}
```

