import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("StorageReference")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class StorageReferenceProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        Elements elementUtils = processingEnv.getElementUtils();
        Types typeUtils = processingEnv.getTypeUtils();

        for (Element element : roundEnv.getElementsAnnotatedWith(StorageReference.class)) {
            if (element.getKind() == ElementKind.FIELD) {
                TypeElement classElement = (TypeElement) element.getEnclosingElement();
                String className = classElement.getSimpleName().toString();
                String packageName = elementUtils.getPackageOf(classElement).getQualifiedName().toString();

                try (PrintWriter writer = new PrintWriter(processingEnv.getFiler().createSourceFile(className + "StorageHandler").openWriter())) {
                    writer.println("package " + packageName + ";");
                    writer.println("import java.util.Map;");
                    writer.println("import java.util.HashMap;");
                    writer.println("public class " + className + "StorageHandler {");

                    for (Element field : classElement.getEnclosedElements()) {
                        if (field.getKind() == ElementKind.FIELD && field.getAnnotation(StorageReference.class) != null) {
                            String fieldName = field.getSimpleName().toString();
                            String fieldType = field.asType().toString();
                            boolean mapKey = field.getAnnotation(StorageReference.class).mapKey();
                            boolean mapValue = field.getAnnotation(StorageReference.class).mapValue();

                            if (mapKey) {
                                writer.println("private Map<String, " + fieldType + "> " + fieldName + "Map = new HashMap<>();");
                                writer.println("public void map" + fieldName + "(String key, " + fieldType + " value) {");
                                writer.println(fieldName + "Map.put(key, value);");
                                writer.println("}");
                            }

                            if (mapValue) {
                                writer.println("private Map<String, " + fieldType + "> " + fieldName + "Map = new HashMap<>();");
                                writer.println("public void map" + fieldName + "(String key, " + fieldType + " value) {");
                                writer.println(fieldName + "Map.put(key, value);");
                                writer.println("}");
                            }
                        }
                    }

                    writer.println("}");
                } catch (IOException e) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, e.getMessage());
                }
            }
        }
        return true;
    }
}
