import java.lang.annotation.*;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Inject {}

class FlowContainer {
    // Implementation of FlowContainer class
}

class DependencyInjector {
    private Map<Class<?>, Object> dependencyMap = new HashMap<>();

    public void registerDependency(Class<?> clazz, Object instance) {
        dependencyMap.put(clazz, instance);
    }

    public void injectDependencies(Object instance) throws IllegalAccessException {
        Class<?> targetClass = instance.getClass();
        for (Field field : targetClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(Inject.class)) {
                Class<?> fieldType = field.getType();
                Object dependencyInstance = dependencyMap.get(fieldType);
                if (dependencyInstance == null) {
                    throw new RuntimeException("Dependency not found for " + fieldType.getName());
                }
                field.setAccessible(true);
                field.set(instance, dependencyInstance);
            }
        }
    }
}

class SampleClass {
