    private FlowContainer flowContainer;

    public void performAction() {
        // Use the injected FlowContainer instance
    }
}

public class Main {
    public static void main(String[] args) throws IllegalAccessException {
        DependencyInjector injector = new DependencyInjector();
        FlowContainer flowContainer = new FlowContainer();
        injector.registerDependency(FlowContainer.class, flowContainer);

        SampleClass sample = new SampleClass();
        injector.injectDependencies(sample);
        sample.performAction();
    }
}
