import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

public class BeanFactory {
    private Map<Class<?>, Object> beans = new HashMap<>();

    public void registerBean(Class<?> beanClass) {
        try {
            Object beanInstance = beanClass.getDeclaredConstructor().newInstance();
            beans.put(beanClass, beanInstance);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void initializeBeans() {
        beans.values().forEach(bean -> {
            injectDependencies(bean);
            callInitMethods(bean);
        });
    }

    public <T> T getBean(Class<T> beanClass) {
        return beanClass.cast(beans.get(beanClass));
    }

    private void injectDependencies(Object bean) {
        Field[] fields = bean.getClass().getDeclaredFields();
        for (Field field : fields) {
            if (field.isAnnotationPresent(Autowired.class)) {
                field.setAccessible(true);
                try {
                    field.set(bean, getBean(field.getType()));
                } catch (IllegalAccessException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private void callInitMethods(Object bean) {
        try {
            bean.getClass().getMethod("setBeanName", String.class).invoke(bean, "BeanName");
            bean.getClass().getMethod("setBeanFactory", BeanFactory.class).invoke(bean, this);
            bean.getClass().getMethod("display").invoke(bean);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

