        this.data = new ArrayList<>();
    }

    public void add(T item) {
        data.add(item);
    }

    public List<T> select(String fieldName, int value) {
        List<T> result = new ArrayList<>();
        for (T item : data) {
            try {
                int fieldValue = (int) item.getClass().getMethod("get" + fieldName.substring(0, 1).toUpperCase() + fieldName.substring(1)).invoke(item);
                if (fieldValue == value) {
                    result.add(item);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
