```java
import java.math.BigInteger;
import java.util.List;

public class FibonacciGenerator {
    public static List<BigInteger> generateFibonacciSequenceUpToLimit(BigInteger limit) {
        List<BigInteger> fibonacciSequence = new ArrayList<>();
        BigInteger a = BigInteger.ZERO;
        BigInteger b = BigInteger.ONE;

        while (a.compareTo(limit) <= 0) {
            fibonacciSequence.add(a);
            BigInteger next = a.add(b);
            a = b;
            b = next;
        }

        return fibonacciSequence;
    }
}

public class Main {
    public static BigInteger sumEvenFibonacciNumbers(BigInteger limit) {
        List<BigInteger> fibonacciSequence = FibonacciGenerator.generateFibonacciSequenceUpToLimit(limit);
        BigInteger sum = BigInteger.ZERO;

        for (BigInteger num : fibonacciSequence) {
            if (num.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO)) {
                sum = sum.add(num);
            }
        }

        return sum;
    }
}
```

In the solution, the `generateFibonacciSequenceUpToLimit` method generates the Fibonacci sequence up to the given limit using the provided algorithm. The `sumEvenFibonacciNumbers` method then calculates the sum of all even Fibonacci numbers less than or equal to the given limit by iterating through the generated Fibonacci sequence and adding the even numbers to the sum.

