public class StringValidator {
    public static void main(String[] args) {
        String input = "ABCD";
        try {
            if (!hasValidLetters(input.toCharArray())) {
                throw new IllegalArgumentException("Provided string contains invalid letters!");
            }
            int[] values = convertToValues(input.toCharArray());
            if (!hasValidFormat(values)) {
                throw new IllegalArgumentException("Provided string has invalid format!");
            }
            System.out.println("String is valid.");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    public static boolean hasValidLetters(char[] letters) {
        for (char letter : letters) {
            if (letter < 'A' || letter > 'J') {
                return false;
            }
        }
        return true;
    }

    public static int[] convertToValues(char[] letters) {
        int[] values = new int[letters.length];
        for (int i = 0; i < letters.length; i++) {
            values[i] = letters[i] - 'A' + 1;
        }
        return values;
    }

    public static boolean hasValidFormat(int[] values) {
        for (int i = 0; i < values.length - 1; i++) {
            if (values[i] + 1 != values[i + 1]) {
                return false;
            }
        }
        return true;
    }
}
