public class RecordSchema {
    private Map<String, Map<String, String>> schemaMap;

    private RecordSchema() {
        schemaMap = new HashMap<>();
    }

    public static RecordSchema getInstance(String schemaString) {
        RecordSchema recordSchema = new RecordSchema();
        String[] schemaEntries = schemaString.split("\n");
        for (String entry : schemaEntries) {
            String[] fields = entry.split(",");
            if (fields.length < 2) {
                throw new IllegalArgumentException("Invalid schema entry: " + entry);
            }
            String className = fields[0];
            String fieldName = fields[1];
            Map<String, String> fieldProperties = new HashMap<>();
            fieldProperties.put("DataType", fields.length > 2 ? fields[2] : "");
            fieldProperties.put("DefaultValue", fields.length > 3 ? fields[3] : "");
            fieldProperties.put("Attributes", fields.length > 4 ? fields[4] : "");
            recordSchema.schemaMap.computeIfAbsent(className, k -> new HashMap<>()).put(fieldName, fieldProperties);
        }
        return recordSchema;
    }

    public Map<String, Map<String, String>> getSchemaMap() {
        return schemaMap;
    }
}
```

