import java.util.ArrayList;
import java.util.List;

public class TabCompletion {
    public List<String> addTabCompletionOptions(String input, int cursorPosition, List<String> completionOptions) {
        String partialInput = input.substring(0, cursorPosition);
        List<String> matchingCompletions = new ArrayList<>();

        for (String option : completionOptions) {
            if (option.startsWith(partialInput)) {
                matchingCompletions.add(option);
            }
        }

        return matchingCompletions;
    }

