import java.util.Collection;
import java.util.HashSet;
import java.util.Set;

public class ObjectManager {
    private Set<String> objectIds;

    public ObjectManager() {
        this.objectIds = new HashSet<>();
    }

    /**
     * Adds the given object IDs to the existing list.
     *
     * @param newObjectIds The collection of object IDs to be added.
     * @throws IllegalStateException If the new object IDs violate the constraint of not mixing physical objects and components.
     */
    public void addObjectIds(Collection<String> newObjectIds) {
