            objectIds.addAll(newObjectIds);
        } else {
            boolean isPhysical = isPhysicalObject(objectIds.iterator().next());
            for (String newId : newObjectIds) {
                if (isPhysical != isPhysicalObject(newId)) {
                    throw new IllegalStateException("Mixing physical objects and components is not allowed.");
                }
            }
            objectIds.addAll(newObjectIds);
        }
