        if (fields.containsKey(key)) {
            fields.put(key, value);
        } else {
            throw new IllegalArgumentException("Field '" + key + "' does not exist");
        }
    }

    public Object getField(String key) {
        if (fields.containsKey(key)) {
            return fields.get(key);
        } else {
            throw new IllegalArgumentException("Field '" + key + "' does not exist");
        }
    }

