import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class App {
    private Connection connection;

    public void connect(String databaseUrl) {
        try {
            connection = DriverManager.getConnection("jdbc:mysql://" + databaseUrl + "/population", "username", "password");
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public District getDistrictPopulation(String districtName) {
        if (districtName.isEmpty()) {
            throw new IllegalArgumentException("District name cannot be empty");
        }

        try {
            String query = "SELECT population FROM districts WHERE name = ?";
            PreparedStatement statement = connection.prepareStatement(query);
            statement.setString(1, districtName);
            ResultSet resultSet = statement.executeQuery();

            if (resultSet.next()) {
                int population = resultSet.getInt("population");
                return new District(districtName, population);
            } else {
                throw new IllegalArgumentException("District not found");
            }
        } catch (SQLException e) {
            e.printStackTrace();
            throw new RuntimeException("Error retrieving district population");
        }
    }
}
```

