public List<Number> findMaxValuesPerRow(Matrix matrix) {
    List<Number> maxValues = new ArrayList<>();
    int rowSize = matrix.getRowSize();
    int columnSize = matrix.getColumnSize();

    for (int i = 0; i < rowSize; i++) {
        Number max = matrix.getValue(i, 0);  // Initialize max with the first value in the row
        for (int j = 1; j < columnSize; j++) {
            Number currentValue = matrix.getValue(i, j);
            if (currentValue.doubleValue() > max.doubleValue()) {
                max = currentValue;  // Update max if a larger value is found
            }
        }
        maxValues.add(max);  // Add the maximum value of the current row to the list
    }

    return maxValues;
}
```

