import org.apache.commons.lang3.tuple.Pair;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.List;

public class CondorCsvMarshallerImpl implements CondorCsvMarshaller {

    @Override
    public Pair<File, File> write(List<Actor> actors, List<Edge> edges, String dir) {
        File actorsFile = new File(dir, "actors.csv");
        File edgesFile = new File(dir, "edges.csv");

        try {
            writeActorsToCsv(actors, actorsFile);
            writeEdgesToCsv(edges, edgesFile);
        } catch (IOException e) {
            // Handle the exception or rethrow as needed
            e.printStackTrace();
        }

        return Pair.of(actorsFile, edgesFile);
    }

    private void writeActorsToCsv(List<Actor> actors, File file) throws IOException {
        try (FileWriter writer = new FileWriter(file)) {
            writer.append("Name,Age,Occupation\n");
            for (Actor actor : actors) {
                writer.append(actor.getName())
                        .append(",")
                        .append(String.valueOf(actor.getAge()))
                        .append(",")
                        .append(actor.getOccupation())
                        .append("\n");
            }
        }
    }

    private void writeEdgesToCsv(List<Edge> edges, File file) throws IOException {
        try (FileWriter writer = new FileWriter(file)) {
            writer.append("SourceActor,TargetActor,RelationshipType\n");
            for (Edge edge : edges) {
                writer.append(edge.getSourceActor().getName())
                        .append(",")
                        .append(edge.getTargetActor().getName())
                        .append(",")
                        .append(edge.getRelationshipType())
                        .append("\n");
            }
        }
    }
