import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public class ListMap<K, V> {
    private List<K> keyList;
    private HashMap<K, V> map;

    public ListMap() {
        keyList = new ArrayList<>();
        map = new HashMap<>();
    }

    public void put(K key, V value) {
        if (map.containsKey(key)) {
            map.put(key, value);
        } else {
            keyList.add(key);
            map.put(key, value);
        }
    }

    public V get(K key) {
        return map.get(key);
    }

    public void remove(K key) {
        if (map.containsKey(key)) {
            keyList.remove(key);
            map.remove(key);
        }
    }

    public int size() {
        return keyList.size();
    }

    public List<K> keys() {
        return new ArrayList<>(keyList);
    }
}
```

This `ListMap` class uses a list to maintain the order of keys and a HashMap to store key-value pairs. The `put`, `get`, `remove`, `size`, and `keys` methods provide the required functionality for the custom data structure.

