import java.util.*;

public class IndentingWriter {
  private StringBuilder o;
  private int indentLevel;

  public IndentingWriter() {
    o = new StringBuilder();
    indentLevel = 0;
  }

  public void write(String text) {
    // Write the given text with proper indentation
    o.append(" ".repeat(2 * indentLevel)).append(text).append("\n");
  }

  public void increaseIndent() {
    // Increase the current indentation level
    indentLevel++;
  }

  public void decreaseIndent() {
    // Decrease the current indentation level
    if (indentLevel > 0) {
      indentLevel--;
    }
  }

  public void resetIndent() {
    // Reset the indentation level to zero
    indentLevel = 0;
  }

  @Override
  public String toString() {
    return o.toString().replace("\n", "\n" + " ".repeat(2 * indentLevel));
  }
}
```

