import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Graph {
    private Map<Integer, List<Integer>> adjacencyList;

    public Graph() {
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(int nodeId) {
        if (!adjacencyList.containsKey(nodeId)) {
            adjacencyList.put(nodeId, new ArrayList<>());
        }
    }

    public void addEdge(int sourceNodeId, int targetNodeId) {
        if (!adjacencyList.containsKey(sourceNodeId)) {
            addNode(sourceNodeId);
        }
        if (!adjacencyList.containsKey(targetNodeId)) {
            addNode(targetNodeId);
        }
        adjacencyList.get(sourceNodeId).add(targetNodeId);
        adjacencyList.get(targetNodeId).add(sourceNodeId); // For undirected graph
    }

    public List<Integer> getAllNodes() {
        return new ArrayList<>(adjacencyList.keySet());
    }

    public List<List<Integer>> getAllEdges() {
        List<List<Integer>> edges = new ArrayList<>();
        for (int source : adjacencyList.keySet()) {
            for (int target : adjacencyList.get(source)) {
                List<Integer> edge = new ArrayList<>();
                edge.add(source);
                edge.add(target);
                if (!edges.contains(edge)) {
                    edges.add(edge);
                }
            }
        }
        return edges;
    }
}
