class UpgradeInfo {
    private long msgsReceived;

    public UpgradeInfo() {
        this.msgsReceived = 0;
    }

    public synchronized long getMsgsReceived() {
        return msgsReceived;
    }

    public synchronized void setMsgsReceived(long msgsReceived) {
        this.msgsReceived = msgsReceived;
    }
}

// MessageTracker class
class MessageTracker {
    private long deadMsgsReceived;
    private List<UpgradeInfo> upgradeInfos;

    public MessageTracker() {
        this.deadMsgsReceived = 0;
        this.upgradeInfos = new ArrayList<>();
    }

    public synchronized long getMsgsReceived() {
        long msgs = deadMsgsReceived;
        for (UpgradeInfo ui : upgradeInfos) {
            msgs += ui.getMsgsReceived();
        }
        return msgs;
    }

    public synchronized void setMsgsReceived(long msgsReceived) {
        this.deadMsgsReceived = msgsReceived;
        for (UpgradeInfo ui : upgradeInfos) {
            ui.setMsgsReceived(msgsReceived);
        }
    }
}
```

