public class SpaceMission {
    public static int calculateTripsToMoon(int spacecraftCapacity, int totalPeople) {
        if (spacecraftCapacity <= 0 || totalPeople <= 0) {
            throw new IllegalArgumentException("Capacity and total people must be positive integers");
        }
        int trips = totalPeople / spacecraftCapacity;
        if (totalPeople % spacecraftCapacity != 0) {
            trips++;
        }
        return trips;
    }

