public class ComponentLayoutAlgorithm {
    private int myHorizontalGap; // assuming this variable is accessible

    public void layoutComponents(Container parent) {
        Rectangle bounds = new Rectangle();
        int availableWidth = parent.getMaximumSize().width;
        int currentX = 0;
        int height = 0;

        final int reservedWidthForOverflow;
        final Component[] componentsWithoutOverflow;
        if (myShowOnOverflowComponent == null) {
            reservedWidthForOverflow = 0;
            componentsWithoutOverflow = parent.getComponents();
        } else {
            reservedWidthForOverflow = myHorizontalGap + myShowOnOverflowComponent.getWidth();
            componentsWithoutOverflow = Arrays.stream(parent.getComponents())
                    .filter(c -> c != myShowOnOverflowComponent)
                    .toArray(Component[]::new);
            myShowOnOverflowComponent.setVisible(false);
        }

        for (Component component : componentsWithoutOverflow) {
            if (currentX + component.getWidth() > availableWidth - reservedWidthForOverflow) {
                currentX = 0;
                height += component.getHeight();
            }
            component.setBounds(currentX, height, component.getWidth(), component.getHeight());
            currentX += component.getWidth() + myHorizontalGap;
        }
    }
}
