import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.context.request.NativeWebRequest;
import org.zalando.nakadi.exceptions.IllegalClientIdException;
import org.zalando.nakadi.exceptions.NakadiException;

@ControllerAdvice
public class CustomExceptionHandler {

    private static final Logger logger = LoggerFactory.getLogger(CustomExceptionHandler.class);

    @ExceptionHandler(IllegalClientIdException.class)
    public ResponseEntity<String> handleIllegalClientIdException(IllegalClientIdException ex, NativeWebRequest request) {
        logger.error("Illegal Client ID Exception: " + ex.getMessage());
        return ResponseEntity.status(400).body("Invalid client ID provided");
    }

    @ExceptionHandler(NakadiException.class)
    public ResponseEntity<String> handleNakadiException(NakadiException ex, NativeWebRequest request) {
        logger.error("Nakadi Exception: " + ex.getMessage());
        return ResponseEntity.status(500).body("An error occurred while processing the request");
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<String> handleHttpMessageNotReadableException(HttpMessageNotReadableException ex, NativeWebRequest request) {
        logger.error("HTTP Message Not Readable Exception: " + ex.getMessage());
        return ResponseEntity.status(400).body("Malformed request body");
    }

    @ExceptionHandler(CustomApplicationException.class)
    public ResponseEntity<String> handleCustomApplicationException(CustomApplicationException ex, NativeWebRequest request) {
        logger.error("Custom Application Exception: " + ex.getMessage());
        return ResponseEntity.status(422).body("Custom application exception occurred");
    }
}
