import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.Method;

@Retention(RetentionPolicy.RUNTIME)
@interface FactorialMethod {
    String value() default "";
}

class FactorialCalculator {
    @FactorialMethod
    public int calculateFactorial(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Factorial is defined only for non-negative integers.");
        }
        int factorial = 1;
        for (int i = 1; i <= number; i++) {
            factorial *= i;
        }
        return factorial;
    }
}

public class Main {
    public static void main(String[] args) {
        FactorialCalculator calculator = new FactorialCalculator();
        Method[] methods = calculator.getClass().getDeclaredMethods();
        for (Method method : methods) {
            if (method.isAnnotationPresent(FactorialMethod.class)) {
                FactorialMethod annotation = method.getAnnotation(FactorialMethod.class);
                System.out.println("Annotated method: " + method.getName());
                System.out.println("Factorial of 5: " + calculator.calculateFactorial(5));
            }
        }
    }
}
```

