public class Props {
    private Map<String, String> properties;

    public Props() {
        this.properties = new HashMap<>();
    }

    public void setProps(Map<String, String> propsMap) {
        for (Map.Entry<String, String> entry : propsMap.entrySet()) {
            properties.put(entry.getKey(), entry.getValue());
        }
    }

    public String getValue(String key) {
        String value = properties.get(key);
        if (value != null) {
            if (value.startsWith("(") && value.contains(")")) {
                int endIndex = value.indexOf(")");
                return value.substring(endIndex + 1);
            }
            return value;
        }
        return null;
    }

    public static void main(String[] args) {
        Props props = new Props();
        Map<String, String> propsMap = new HashMap<>();
        propsMap.put("string-prop", "testValue");
        propsMap.put("endpoint-prop", "(endpoint)test");
        propsMap.put("file-prop", "(file)src/test/resources/util-input/props.txt");
        props.setProps(propsMap);

        System.out.println(props.getValue("string-prop"));  // Output: testValue
        System.out.println(props.getValue("endpoint-prop"));  // Output: test
        System.out.println(props.getValue("file-prop"));  // Output: src/test/resources/util-input/props.txt
        System.out.println(props.getValue("invalid-prop"));  // Output: null
    }
}
