import org.reactivestreams.Subscriber;
import org.reactivestreams.Subscription;

public final class FlowableRepeat<T> extends Flowable<T> {

    private final T value;
    private final long count;

    public FlowableRepeat(T value, long count) {
        this.value = value;
        this.count = count;
    }

    @Override
    protected void subscribeActual(Subscriber<? super T> subscriber) {
        subscriber.onSubscribe(new RepeatSubscription(subscriber, value, count));
    }

    private static class RepeatSubscription<T> implements Subscription {
        private final Subscriber<? super T> subscriber;
        private final T value;
        private long remaining;

        RepeatSubscription(Subscriber<? super T> subscriber, T value, long count) {
            this.subscriber = subscriber;
            this.value = value;
            this.remaining = count;
        }

        @Override
        public void request(long n) {
            if (n <= 0) {
                subscriber.onError(new IllegalArgumentException("Non-positive request"));
                return;
            }
            for (long i = 0; i < n && remaining > 0; i++) {
                subscriber.onNext(value);
                remaining--;
            }
            if (remaining == 0) {
                subscriber.onComplete();
            }
        }

        @Override
        public void cancel() {
            remaining = 0;
        }
    }
}
```

In the solution, the `FlowableRepeat<T>` class extends `Flowable<T>` and implements the `subscribeActual` method to handle the subscription logic. It creates a custom `RepeatSubscription` class that implements the `Subscription` interface to manage the emission of the `value` the specified number of times. The `request` method is used to emit the `value` based on the requested amount, and the `cancel` method is implemented to stop further emissions if needed.

