        this.memoryUsedInBytes = bytes;
    }

    public long totalMemoryUsed() {
        return this.memoryUsedInBytes;
    }

    private long convertToUnit(long bytes, MonitoringUnit unit) {
        switch (unit) {
            case BYTES:
                return bytes;
            case KILOBYTES:
                return bytes / 1024;
            case MEGABYTES:
                return bytes / (1024 * 1024);
            case GIGABYTES:
                return bytes / (1024 * 1024 * 1024);
            default:
                throw new IllegalArgumentException("Unsupported monitoring unit: " + unit);
        }
    }

    public static class Builder {
        private MonitoringUnit unit;
        private long memoryUsedInBytes;

        public Builder unit(MonitoringUnit unit) {
            this.unit = unit;
            return this;
        }

        public Builder memoryUsed(long memoryUsedInBytes) {
            this.memoryUsedInBytes = memoryUsedInBytes;
            return this;
