public class ServerDetailsExtractor {
    public static void main(String[] args) {
        String input = "[ActivationGroupImpl[UnicastServerRef [liveRef: [endpoint:[172.16.20.11:12345](local),objID:[de39d9c:15269e6d8bf:-7fc1, -9046794842107247609]]";
        String formattedOutput = extractServerDetails(input);
        System.out.println(formattedOutput);
    }

    public static String extractServerDetails(String input) {
        Pattern objIdPattern = Pattern.compile("objID:\\[(.*?)\\]");
        Pattern endpointPattern = Pattern.compile("endpoint:\\[(.*?)\\]");

        Matcher objIdMatcher = objIdPattern.matcher(input);
        Matcher endpointMatcher = endpointPattern.matcher(input);

        String objectId = "";
        String endpoint = "";

        if (objIdMatcher.find()) {
            objectId = objIdMatcher.group(1);
        }

        if (endpointMatcher.find()) {
            endpoint = endpointMatcher.group(1);
        }

        return "Object ID: " + objectId + "\nEndpoint: " + endpoint;
    }
}
