import java.util.Arrays;
import java.util.Comparator;

public class IndexEntryElementComparator {
    public static IndexEntryElement[] customComparator(IndexEntryElement[] elements) {
        Arrays.sort(elements, new Comparator<IndexEntryElement>() {
            @Override
            public int compare(IndexEntryElement o1, IndexEntryElement o2) {
                if (o1.getElement().equals(o2.getElement()))
                    return 0;
                if (o1.getSignature() != o2.getSignature())
                    return Long.signum(o1.getSignature() - o2.getSignature());
                return Integer.signum(o1.getElement().hashCode() - o2.getElement().hashCode());
            }
        });
        return elements;
    }
}
```

