public class TrafficLightSystem {
    public static void main(String[] args) {
        Thread greenLight = new Thread(new Light("Green", 3000));
        Thread yellowLight = new Thread(new Light("Yellow", 1000));
        Thread redLight = new Thread(new Light("Red", 2000));

        greenLight.start();

        while (true) {
            try {
                greenLight.join();
                yellowLight.start();
                yellowLight.join();
                redLight.start();
                redLight.join();
                greenLight = new Thread(new Light("Green", 3000));
                yellowLight = new Thread(new Light("Yellow", 1000));
                redLight = new Thread(new Light("Red", 2000));
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    static class Light implements Runnable {
        private String color;
        private long duration;

        public Light(String color, long duration) {
            this.color = color;
            this.duration = duration;
        }

        @Override
        public void run() {
            try {
                System.out.println(color + " light is on");
                Thread.sleep(duration);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}
