import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class GitHubInfoParser {
    public static GitHubInfo parseGitHubInfo(String codeSnippet) {
        Pattern pattern = Pattern.compile("<reponame>(\\w+)/(\\w+)<gh_stars>(\\d+)");
        Matcher matcher = pattern.matcher(codeSnippet);

        if (matcher.find()) {
            String organizationName = matcher.group(1);
            String repositoryName = matcher.group(2);
            int stars = Integer.parseInt(matcher.group(3));
            return new GitHubInfo(repositoryName, organizationName, stars);
        } else {
            return null; // Handle invalid input
        }
    }

    public static void main(String[] args) {
        String codeSnippet = "<reponame>GeniusV/common-utils<gh_stars>0\npackage com.geniusver.util;";
        GitHubInfo gitHubInfo = parseGitHubInfo(codeSnippet);
        System.out.println(gitHubInfo);
    }
}

class GitHubInfo {
    private String repositoryName;
    private String organizationName;
    private int stars;

    public GitHubInfo(String repositoryName, String organizationName, int stars) {
        this.repositoryName = repositoryName;
        this.organizationName = organizationName;
        this.stars = stars;
    }

    @Override
    public String toString() {
        return "Repository Name: " + repositoryName + ", Organization/User Name: " + organizationName + ", Stars: " + stars;
    }
}
