public class Earth3D {
    public Vector3d convertToModel(GeographicPosition position, Vector3d modelOrigin) {
        // Implementation to convert geographic position to 3D model coordinates
        double x = (position.getLongitude() - modelOrigin.getLongitude()) * Math.cos(position.getLatitude()) * Math.cos(position.getLongitude());
        double y = (position.getLatitude() - modelOrigin.getLatitude()) * Math.cos(position.getLatitude()) * Math.sin(position.getLongitude());
        double z = (position.getAltitude() - modelOrigin.getAltitude());
        return new Vector3d(x, y, z);
    }

    public GeographicPosition convertToPosition(Vector3d modelCoordinates, Vector3d modelOrigin) {
        // Implementation to convert 3D model coordinates to geographic position
        double longitude = Math.atan2(modelCoordinates.getY(), modelCoordinates.getX()) + modelOrigin.getLongitude();
        double latitude = Math.atan2(modelCoordinates.getZ(), Math.sqrt(modelCoordinates.getX() * modelCoordinates.getX() + modelCoordinates.getY() * modelCoordinates.getY())) + modelOrigin.getLatitude();
        double altitude = modelCoordinates.getZ() + modelOrigin.getAltitude();
        return new GeographicPosition(latitude, longitude, altitude);
    }
}
