public interface ComplexOperation {
    ComplexOperation add(ComplexOperation other);
    ComplexOperation subtract(ComplexOperation other);
    String getDescription();
}

public class ComplexOperationImpl implements ComplexOperation {
    private String description;
    private double realPart;
    private double imaginaryPart;

    public ComplexOperationImpl(String description, double realPart, double imaginaryPart) {
        this.description = description;
        this.realPart = realPart;
        this.imaginaryPart = imaginaryPart;
    }

    @Override
    public ComplexOperation add(ComplexOperation other) {
        ComplexOperationImpl otherComplex = (ComplexOperationImpl) other;
        double newRealPart = this.realPart + otherComplex.realPart;
        double newImaginaryPart = this.imaginaryPart + otherComplex.imaginaryPart;
        return new ComplexOperationImpl("Sum of " + this.description + " and " + otherComplex.description, newRealPart, newImaginaryPart);
    }

    @Override
    public ComplexOperation subtract(ComplexOperation other) {
        ComplexOperationImpl otherComplex = (ComplexOperationImpl) other;
        double newRealPart = this.realPart - otherComplex.realPart;
        double newImaginaryPart = this.imaginaryPart - otherComplex.imaginaryPart;
        return new ComplexOperationImpl("Difference of " + this.description + " and " + otherComplex.description, newRealPart, newImaginaryPart);
    }

    @Override
    public String getDescription() {
        return description;
    }
}
```

