package org.jeecg.rpc.serialize.impl;

import com.caucho.hessian.io.HessianInput;
import com.caucho.hessian.io.HessianOutput;
import org.jeecg.rpc.serialize.Serializer;
import org.jeecg.rpc.util.XxlRpcException;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class HessianSerializer implements Serializer {

    @Override
    public byte[] serialize(Object obj) {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        HessianOutput hessianOutput = new HessianOutput(byteArrayOutputStream);
        try {
            hessianOutput.writeObject(obj);
            hessianOutput.flush();
            return byteArrayOutputStream.toByteArray();
        } catch (IOException e) {
            throw new XxlRpcException("Hessian serialization error", e);
        } finally {
            try {
                hessianOutput.close();
                byteArrayOutputStream.close();
            } catch (IOException e) {
                // handle or log the exception
            }
        }
    }

    @Override
    public <T> T deserialize(byte[] data, Class<T> clazz) {
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
        HessianInput hessianInput = new HessianInput(byteArrayInputStream);
        try {
            return clazz.cast(hessianInput.readObject());
        } catch (IOException e) {
            throw new XxlRpcException("Hessian deserialization error", e);
        } finally {
            try {
                hessianInput.close();
                byteArrayInputStream.close();
            } catch (IOException e) {
                // handle or log the exception
            }
        }
    }
}
```

In the solution, the `HessianSerializer` class implements the `Serializer` interface, which defines the `serialize` and `deserialize` methods. The `serialize` method uses the Hessian library to serialize the input object into a byte array, while the `deserialize` method deserializes the byte array back into the original object using the Hessian library. The implementation also handles potential IO exceptions and wraps them in a custom `XxlRpcException` for error handling.

