public class Vector2D {
    private double dX;
    private double dY;

    // Constructor and other methods are not shown

    public double getDX() {
        return dX;
    }

    public double getDY() {
        return dY;
    }

    public double magnitude() {
        return Math.sqrt(dX * dX + dY * dY);
    }

    public Vector2D add(Vector2D other) {
        return new Vector2D(dX + other.getDX(), dY + other.getDY());
    }

