public class Assertion {
    private String assertionType;

    /**
     * Sets the assertion type.
     * @param assertionType the assertion type to be set
     */
    public void setAssertionType(String assertionType) {
        this.assertionType = assertionType;
    }

    /**
     * Gets the assertion type.
     * @return the assertion type
     */
    public String getAssertionType() {
        return assertionType;
    }

    /**
     * Checks if the given value satisfies the assertion type.
     * @param value the value to be checked
     * @param expected the expected value for comparison
     * @return true if the value satisfies the assertion type, false otherwise
     */
    public boolean checkAssertion(int value, int expected) {
        switch (assertionType) {
            case "EQUALS":
                return value == expected;
            case "NOT_EQUALS":
                return value != expected;
            case "GREATER_THAN":
                return value > expected;
            case "LESS_THAN":
                return value < expected;
            case "NULL":
                return value == 0;
            default:
                throw new IllegalArgumentException("Invalid assertion type");
        }
    }
