    ByteBuffer vxlanDataBB = ByteBuffer.wrap(udpPayload); // Wrap the payload in a ByteBuffer
    vxlanDataBB.position(4); // Set the position to skip the first 4 bytes (VXLAN header)

    // Extract the VXLAN Network Identifier (VNID) from the ByteBuffer
    int vnid = vxlanDataBB.getInt() >> 8; // Shift right by 8 bits to extract the VNID

    // Deserialize the inner Ethernet packet from the UDP payload, skipping the VXLAN header
    Ethernet innerEtherPacket = new Ethernet();
    innerEtherPacket.deserialize(udpPayload, 8, udpPayload.length - 8);

