    public static LibraryNumber parse(String input) throws InvalidFormat {
        String[] parts = input.split("-");
        if (parts.length != 2 || !parts[0].matches("[a-zA-Z0-9]+") || !parts[1].matches("\\d+")) {
            throw new InvalidFormat("Invalid library number format: " + input);
        }
        return new LibraryNumber(parts[0], parts[1]);
